import itertools

def is_good(n, good_set):
    s_n = str(n)
    if len(s_n) == 1:
        return True
    for i in range(len(s_n)):
        new_s = s_n[:i] + s_n[i+1:]
        if not new_s: continue
        m_prime = int(new_s)
        if m_prime in good_set and n % m_prime == 0:
            return True
    return False

good_numbers = set()
for i in range(1, 10):
    good_numbers.add(i)

for length in range(2, 10):
    new_good_numbers = set()
    for digits in itertools.permutations(range(1, 10), length):
        n = int("".join(map(str, digits)))
        if is_good(n, good_numbers):
            new_good_numbers.add(n)
    good_numbers.update(new_good_numbers)
    print(f"Length {length}: {len(new_good_numbers)} numbers")

print("Largest:", max(good_numbers))

